 migrate(){this.state={...structuredClone(this.defaults),...this.state};for(const k of ['accounts','transactions','assets','goldJewelry','realEstate','liabilities','budgets','goals','recurring','snapshots','imports'])if(!Array.isArray(this.state[k]))this.state[k]=[];if(!Array.isArray(this.state.expenseCategories)||!this.state.expenseCategories.length)this.state.expenseCategories=structuredClone(this.defaults.expenseCategories);this.state.settings={...this.defaults.settings,...(this.state.settings||{})};this.state.sync={...this.defaults.sync,...(this.state.sync||{})};this.state.essentials={...this.defaults.essentials,...(this.state.essentials||{})};this.state.security={...this.defaults.security,...(this.state.security||{})};for(const a of this.state.assets){if(!a.type||/imported investment/i.test(String(a.type))){a.type=this.inferAssetType(a.name,a.type,a.ticker||a.symbol||'')}this.backfillImportedAssetFields(a)}for(const t of this.state.transactions){this.normalizeTransactionRecord(t)}this.ensureProfiles()},
 ensureProfiles(){const keys=['currency','expenseCategories','accounts','transactions','assets','goldJewelry','realEstate','liabilities','budgets','goals','recurring','snapshots','essentials'];if(!Array.isArray(this.state.profiles)||!this.state.profiles.length){const snap={};keys.forEach(k=>snap[k]=structuredClone(this.state[k]));const id=crypto.randomUUID();this.state.profiles=[{id,name:this.state.profile||'Personal',...snap}];this.state.currentProfileId=id}else if(!this.state.profiles.find(p=>p.id===this.state.currentProfileId))this.state.currentProfileId=this.state.profiles[0].id;this.loadProfile(this.state.currentProfileId,false)},
 syncCurrentProfile(){const p=this.state.profiles?.find(x=>x.id===this.state.currentProfileId);if(!p)return;for(const k of ['currency','expenseCategories','accounts','transactions','assets','goldJewelry','realEstate','liabilities','budgets','goals','recurring','snapshots','essentials'])p[k]=structuredClone(this.state[k]);p.name=this.state.profile||p.name},
