 async persist(initial=false,saltOverride=null,opts={}){if(!this.state||!this.cryptoKey)return;this.syncCurrentProfile();this.state.updatedAt=new Date().toISOString();const old=await this.idbGet();let passwordWrap=old?.passwordWrap;let pinWrap=this.state.security?.pinWrap||null;let biometric=this.state.security?.biometric||null;if(initial&&opts.dataKey&&opts.pass)passwordWrap=await this.wrapKey(await crypto.subtle.exportKey('raw',opts.dataKey),opts.pass);if(opts.migrateFromLegacy&&opts.pass){passwordWrap=await this.wrapKey(await crypto.subtle.exportKey('raw',this.cryptoKey),opts.pass);pinWrap=null;biometric=null;this.state.security={pinWrap:null,biometric:null}}const enc=await this.encrypt(this.state,this.cryptoKey);await this.idbPut({version:3,passwordWrap,pinWrap,biometric,pinEnabled:!!pinWrap,biometricEnabled:!!biometric,...enc});if(!initial&&this.state.sync?.autoSync)this.scheduleDriveSync()},
