 async deleteProfile(id){if((this.state.profiles||[]).length<=1)return alert('At least one profile must remain.');const p=this.state.profiles.find(x=>x.id===id);if(!p)return;if(!confirm(`Delete profile "${p.name}" and all its data?`))return;if(!confirm('FINAL CONFIRMATION: permanently delete this profile.'))return;this.state.profiles=this.state.profiles.filter(x=>x.id!==id);if(id===this.state.currentProfileId)this.loadProfile(this.state.profiles[0].id,false);await this.persist();document.getElementById('formModal')?.remove();this.render()},
