 showSetup(){document.getElementById('app').innerHTML=`<div class="modal"><div class="modalbox"><img src="icons/finmate-icon-192.png?v=3.3" class="logo"><h2>Welcome to FinMate</h2><p class="note">Create a private local vault. Your financial records are encrypted before storage.</p><div class="field"><label>Master password</label><input id="pw1" type="password" autocomplete="new-password"></div><div class="field"><label>Confirm password</label><input id="pw2" type="password"></div><button class="btn primary full" onclick="APP.setupGo()">Create local vault</button><p class="note">Keep this password safe. It is the root of your local encryption key.</p></div></div>`},
 showUnlock(rec){this.pendingRec=rec;const pinReady=!!(rec?.pinWrap||rec?.pinEnabled),bioReady=!!(rec?.biometric||rec?.biometricEnabled);const methods=[pinReady?`<button class="unlock-choice" onclick="APP.showUnlockForm('pin')"><span class="unlock-icon">⌨</span><span><b>4-digit PIN</b><small>Use your FinMate PIN</small></span></button>`:'',bioReady?`<button class="unlock-choice" onclick="APP.showUnlockForm('bio')"><span class="unlock-icon">☝</span><span><b>Fingerprint / biometrics</b><small>Use your device security</small></span></button>`:'',`<button class="unlock-choice" onclick="APP.showUnlockForm('password')"><span class="unlock-icon">🔑</span><span><b>Master password</b><small>Recovery method</small></span></button>`].filter(Boolean).join('');document.getElementById('app').innerHTML=`<div class="modal"><div class="modalbox unlockbox"><img src="icons/finmate-icon-192.png?v=3.3" class="logo"><h2>Unlock FinMate</h2><p class="note">Choose how you want to unlock this vault.</p><div class="unlock-choices">${methods}</div><div id="unlockForm"></div><p class="note">Forgotten password/PIN cannot be retrieved by FinMate. Use your password manager or a securely stored recovery record. If you know the master password, unlock with it and set a new PIN in Settings. PIN and biometric unlock are local to this browser/device.</p></div></div>`},
 showUnlockForm(mode){const box=document.getElementById('unlockForm');if(!box)return;if(mode==='pin'){box.innerHTML=`<div class="unlock-form"><div class="field"><label>4-digit PIN</label><input id="pinUnlockInput" inputmode="numeric" pattern="\d{4}" maxlength="4" type="password" autocomplete="one-time-code" placeholder="••••" oninput="this.value=this.value.replace(/\D/g,'').slice(0,4)" onkeydown="if(event.key==='Enter')APP.unlockPinGo()"></div><button class="btn primary full" onclick="APP.unlockPinGo()">Unlock with PIN</button></div>`}else if(mode==='bio'){box.innerHTML=`<div class="unlock-form"><button class="btn primary full" onclick="APP.unlockBiometricGo()">Unlock with fingerprint / device biometrics</button></div>`}else{box.innerHTML=`<div class="unlock-form"><div class="field"><label>Master password</label><input id="pw" type="password" autocomplete="current-password" onkeydown="if(event.key==='Enter')APP.unlockGo()"></div><button class="btn primary full" onclick="APP.unlockGo()">Unlock with password</button></div>`}setTimeout(()=>box.querySelector('input,button')?.focus(),0)},
 async setupGo(){const a=document.getElementById('pw1').value,b=document.getElementById('pw2').value;if(a.length<8)return alert('Use at least 8 characters.');if(a!==b)return alert('Passwords do not match.');await this.createVault(a)},
